WITH observed(kind,a,b,c) AS (SELECT 'schema', type, name, tbl_name FROM sqlite_schema WHERE name IN ('t1','t2','t3','i1','i2') UNION ALL SELECT 'row','t1',quote(x),'' FROM t1 UNION ALL SELECT 'row','t2',quote(y),'' FROM t2 UNION ALL SELECT 'row','t3',quote(z),'' FROM t3 UNION ALL SELECT 'stat',tbl,coalesce(idx,''),stat FROM sqlite_stat1) SELECT kind,a,b,c FROM observed ORDER BY kind,a,b,c;